import 'package:cephalopod/core/board/models/player_ui.dart';
import 'package:cephalopod/core/board/models/role_ui.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'side_ui.freezed.dart';

/// One side of the board, as the screen shows it: a numbered player between
/// two people, or the person or the computer against the computer.
///
/// Plain data generated by freezed (docs/adr/0011, docs/adr/0015).
@freezed
abstract class SideUi with _$SideUi {
  const factory SideUi({
    /// The side's number, which picks its dice colours.
    required PlayerUi player,

    /// Who the side is to the person at the screen, which picks how it is
    /// named.
    required RoleUi role,
  }) = _SideUi;
}
